#include <algorithm>
#include <fstream>
int main() {
    std::ifstream in("square.in");
    std::ofstream out("square.out");
    int left = 11, bottom = 11, right = 0, top = 0;
    for (int rectangle = 0; rectangle < 2; ++rectangle) {
        int x1, y1, x2, y2;
        in >> x1 >> y1 >> x2 >> y2;
        left = std::min(left, x1);
        bottom = std::min(bottom, y1);
        right = std::max(right, x2);
        top = std::max(top, y2);
    }
    const int side = std::max(right - left, top - bottom);
    out << side * side << '\n';
}
