#include <algorithm>
#include <array>
#include <fstream>
#include <string>
int main() {
    std::ifstream in("blocks.in");
    std::ofstream out("blocks.out");
    int n;
    in >> n;
    std::array<int, 26> total{};
    for (int board = 0; board < n; ++board) {
        std::string first, second;
        in >> first >> second;
        std::array<int, 26> a{}, b{};
        for (char ch : first) ++a[ch - 'a'];
        for (char ch : second) ++b[ch - 'a'];
        for (int letter = 0; letter < 26; ++letter)
            total[letter] += std::max(a[letter], b[letter]);
    }
    for (int count : total) out << count << '\n';
}
