#include <fstream>
#include <string>
int main() {
    std::ifstream in("cowsignal.in");
    std::ofstream out("cowsignal.out");
    int rows, columns, factor;
    in >> rows >> columns >> factor;
    for (int row = 0; row < rows; ++row) {
        std::string original, expanded;
        in >> original;
        expanded.reserve(columns * factor);
        for (char ch : original) expanded.append(factor, ch);
        for (int copy = 0; copy < factor; ++copy) out << expanded << '\n';
    }
}
